konsole_tabs:
/* Generated by ~/.config/plasma-rice/rice.py from the wallpaper palette. Do not edit. */
QTabBar { background: rgba(11,15,26, 217); }
QTabBar::tab {
    background: transparent; color: #717a92;
    border: 1px solid transparent; border-radius: 10px;
    padding: 4px 12px; margin: 8px 2px 2px 2px;
    min-width: 7em; max-width: 22em;
}
QTabBar::tab:first { margin-left: 12px; }
QTabBar::tab:hover:!selected { background: rgba(218,225,242, 20); color: #a9b1c6; }
QTabBar::tab:selected {
    background: rgba(156,193,241, 41); color: #dae1f2;
    border-color: rgba(156,193,241, 82);
}

zen:
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py from the wallpaper palette. Do not edit. */
:root, :host(:is(.anonymous-content-host, notification-message)) {
  --zen-primary-color: #9cc1f1 !important;
  --zen-branding-dark: #0b0f1a !important;
  --zen-colors-primary: color-mix(in srgb, #9cc1f1 22%, #0f131f) !important;
  --zen-colors-secondary: color-mix(in srgb, #9cc1f1 32%, #0f131f) !important;
  --zen-colors-tertiary: #060913 !important;
  --zen-colors-hover-bg: color-mix(in srgb, #9cc1f1 14%, #131723) !important;
  --zen-colors-primary-foreground: #dae1f2 !important;
  --zen-colors-border: rgba(53,61,80, 0.55) !important;
  --zen-colors-border-contrast: rgba(53,61,80, 0.3) !important;
  --zen-colors-input-bg: #131723 !important;
  --zen-input-border-color: #353d50 !important;
  --zen-dialog-background: #0f131f !important;
  --zen-urlbar-background: #131723 !important;
  --zen-main-browser-background: linear-gradient(135deg, rgba(32,47,66, 0.72) 0%, rgba(6,9,19, 0.84) 52%, rgba(37,50,33, 0.68) 100%) !important;
  --zen-main-browser-background-toolbar: linear-gradient(135deg, rgba(32,47,66, 0.72) 0%, rgba(6,9,19, 0.84) 52%, rgba(37,50,33, 0.68) 100%) !important;
  --toolbox-textcolor: #dae1f2 !important;
  --toolbar-field-color: #dae1f2 !important;
  --arrowpanel-background: #131723 !important;
  --arrowpanel-color: #dae1f2 !important;
  --arrowpanel-border-color: rgba(53,61,80, 0.6) !important;
  --panel-separator-color: rgba(53,61,80, 0.6) !important;
  --focus-outline-color: #9cc1f1 !important;
  --zen-sidebar-themed-icon-fill: #a9b1c6 !important;
}

/* Zen paints the workspace gradient on these layers and sets its variables inline on them,
   so override the layers themselves (::before is the cross-fade target while switching spaces) */
.zen-browser-generic-background::after,
.zen-browser-generic-background::before {
  background: linear-gradient(135deg, rgba(32,47,66, 0.72) 0%, rgba(6,9,19, 0.84) 52%, rgba(37,50,33, 0.68) 100%) !important;
}

/* selected tab: a soft accent wash with a hairline, instead of plain white */
.tabbrowser-tab:is([selected], [multiselected]) .tab-background {
  background-color: rgba(156,193,241, 0.16) !important;
  box-shadow: inset 0 0 0 1px rgba(156,193,241, 0.32) !important;
}
.tabbrowser-tab:not([selected]):hover .tab-background {
  background-color: rgba(218,225,242, 0.07) !important;
}

/* command bar / url bar popup */
#urlbar[breakout-extend] > .urlbar-background,
#urlbar[breakout-extend] #urlbar-background {
  background-color: #131723 !important;
  border: 1px solid rgba(53,61,80, 0.7) !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45) !important;
}
.urlbarView-row[selected] {
  background-color: rgba(156,193,241, 0.18) !important;
}

/* menus and popups */
menupopup, panel {
  --panel-background: #131723 !important;
  --panel-color: #dae1f2 !important;
  --panel-border-color: rgba(53,61,80, 0.6) !important;
}
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py. Do not edit. */
:root {
  scrollbar-color: rgba(93,102,123, 0.7) transparent;
}
@-moz-document url("about:blank"), url("about:newtab"), url("about:home"), url("about:privatebrowsing") {
  html, body { background-color: #0b0f1a !important; }
}
